'use strict';
(()=>{
const side=document.querySelector('aside nav'),anchor=[...side.querySelectorAll('button')].find(b=>b.textContent.trim()==='Сценарии');
const nav=document.createElement('button');nav.innerHTML='<svg class="icon" aria-hidden="true"><use href="icons.svg#send"></use></svg><span>Репетиции</span>';anchor.after(nav);
const page=document.createElement('main');page.id='rehearsal-page';page.hidden=true;
page.innerHTML=`<div class="breadcrumb">Коммуникации / Сквозная репетиция</div><div class="heading"><div><h1>Сквозная репетиция</h1><p>Сценарий → проверки → письмо → события → решение</p></div><button class="outline" id="rh-refresh">Обновить</button></div>
<div class="demo"><b>Без отправки</b><span>Письма только подготавливаются. Доставка неизвестна. Источник и версии фиксируются при старте; местные ограничения дополнены общим контролем частоты по email. При его включении часы общие со сценариями. Рабочие согласия и база не меняются.</span></div><p id="rh-status" role="status"></p>
<section class="panel"><h2>Новая репетиция</h2><form id="rh-create"><div class="auto-grid"><label>Сохранённый сценарий<select id="rh-scenario" required></select></label><label>Проверочное имя<input id="rh-name" maxlength="250" value="Тестовый клиент"></label><label>Проверочная компания<input id="rh-company" maxlength="250" value="OVER"></label><label>Проверочный город<input id="rh-city" maxlength="250" value="Алматы"></label></div><p>Значения персонализации общие для тестовых получателей. Новая репетиция начинает отдельный проход сценария; повторный вход внутри неё не выполняется.</p><button class="outline" type="submit">Начать сквозную репетицию</button></form></section>
<section class="panel"><label>Репетиция<select id="rh-session"></select></label><p id="rh-summary"></p><h3 id="rh-clock"></h3><div class="actions" id="rh-controls"><button class="outline" data-action="tick">Пересчитать условия</button><button class="outline" data-minutes="15">+15 минут</button><button class="outline" data-minutes="60">+1 час</button><button class="outline" data-minutes="1440">+1 день</button><button class="outline" data-minutes="10080">+7 дней</button><button class="outline" data-action="pause">Пауза</button><button class="outline" data-action="resume">Продолжить</button><button class="outline" data-action="cancel">Отменить шаги</button></div><div class="stats" id="rh-counts"></div>
<form id="rh-filters" class="auto-grid"><label>Поиск email<input id="rh-query" type="search" maxlength="254"></label><label>Состояние участника<select id="rh-state"><option value="">Все</option><option value="waiting">Ожидает</option><option value="completed">Шаги завершены</option><option value="blocked">Проверка не пройдена</option><option value="exited">Вышел из условий</option><option value="excluded">Исключён</option><option value="cancelled">Отменён</option><option value="safety_stopped">Остановлено защитой</option></select></label><label>Событие журнала<select id="rh-kind"><option value="">Все</option></select></label><label>Порядок журнала<select id="rh-direction"><option value="desc">Сначала новые</option><option value="asc">Сначала старые</option></select></label><button class="outline">Применить фильтры</button></form>
<h3>Участники</h3><p id="rh-member-note"></p><div class="table-scroll" id="rh-members"></div><h3>Подготовленные письма</h3><p>Последние 100 писем по поиску. «Открытие», «Переход» и «Отписка» создают тестовые события собственного учёта. Повтор одного события не увеличивает счётчик. Открытие не подтверждает прочтение; только переход меняет пассивную аудиторию на активную.</p><div class="table-scroll" id="rh-letters"></div>
<section id="rh-preview" hidden><h3>Проверки и письмо</h3><p id="rh-subject"></p><div id="rh-delivery-history"></div><div id="rh-checks"></div><iframe id="rh-frame" title="Безопасный предпросмотр репетиции" sandbox="" referrerpolicy="no-referrer"></iframe><p>Предпросмотр не загружает пиксель, внешние изображения и не открывает ссылки. Проверочные события создаются кнопками у письма.</p></section>
<h3>Журнал цепочки</h3><div class="table-scroll" id="rh-logs"></div><div class="actions"><button class="outline" id="rh-prev">Назад</button><span id="rh-pagination"></span><button class="outline" id="rh-next">Далее</button></div></section>`;
document.body.append(page);const outcomeFilter=document.createElement('label');outcomeFilter.textContent='Состояние тестовой доставки (письма)';const outcomeSelect=document.createElement('select');outcomeSelect.id='rh-delivery-state';outcomeSelect.add(new Option('Все результаты',''));outcomeFilter.append(outcomeSelect);document.getElementById('rh-filters').prepend(outcomeFilter);const explanation=document.createElement('p');explanation.id='rh-delivery-note';const detailLabel=document.createElement('label');detailLabel.textContent='Описание тестового результата (необязательно)';const detailInput=document.createElement('input');detailInput.id='rh-delivery-detail';detailInput.maxLength=500;detailLabel.append(detailInput);document.getElementById('rh-letters').before(explanation,detailLabel);
const $=key=>document.getElementById('rh-'+key),states={running:'Идёт репетиция',paused:'На паузе',cancelled:'Отменена',waiting:'Ожидает',completed:'Шаги завершены',blocked:'Проверка не пройдена',exited:'Вышел из условий',excluded:'Исключён',safety_stopped:'Остановлено защитой'};
let id='',scenarios=[],busy=false,number=1,current=null,generation=0;
function policyFields(prefix){return `<label class="rh-safety-toggle"><input type="checkbox" id="${prefix}-enabled" checked>Включить автоматическую остановку</label><div class="auto-grid"><label>Минимум писем с тестовым результатом<input id="${prefix}-sample" type="number" min="1" max="10000" value="20" required></label><label>Любые ошибки, порог %<input id="${prefix}-errors" type="number" min="0" max="100" step="0.01" value="10" required></label><label>Постоянные ошибки, порог %<input id="${prefix}-permanent" type="number" min="0" max="100" step="0.01" value="5" required></label><label>Жалобы, порог %<input id="${prefix}-complaints" type="number" min="0" max="100" step="0.01" value="0.1" required></label></div>`;}
const newPolicy=document.createElement('fieldset');newPolicy.innerHTML='<legend>Защита новой репетиции</legend>'+policyFields('rh-new-safety');$('create').querySelector('[type=submit]').before(newPolicy);
const safetyPanel=document.createElement('section');safetyPanel.id='rh-safety';safetyPanel.innerHTML=`<h2>Автоматическая остановка</h2><div id="rh-safety-stop" role="alert" hidden></div><p>Проверка отдельно по каждой рассылке за всю выбранную репетицию. Учитываются разные письма с заданным тестовым результатом; повторы не увеличивают выборку. Остановка срабатывает строго выше порога после достижения минимальной выборки. Останавливается вся эта репетиция, включая повторы.</p><form id="rh-safety-form">${policyFields('rh-safety')}<button class="outline">Сохранить пороги этой репетиции</button></form><p id="rh-safety-note"></p><div class="table-scroll" id="rh-safety-metrics"></div>`;$('controls').after(safetyPanel);
function readPolicy(prefix){return {enabled:document.getElementById(prefix+'-enabled').checked,min_sample:Number(document.getElementById(prefix+'-sample').value),errors_percent:document.getElementById(prefix+'-errors').value,permanent_percent:document.getElementById(prefix+'-permanent').value,complaints_percent:document.getElementById(prefix+'-complaints').value};}
function safetyReport(data){const p=data.policy;for(const [field,key]of [['sample','min_sample'],['errors','errors_percent'],['permanent','permanent_percent'],['complaints','complaints_percent']])document.getElementById('rh-safety-'+field).value=p[key];$('safety-enabled').checked=p.enabled;$('safety-stop').hidden=!data.stop;$('safety-stop').textContent=data.stop?`${data.stop.reason} Остановка: ${date(data.stop.clock_at)}. Причина сохранена; продолжение запрещено. Для нового прохода проверьте настройки и создайте новую репетицию.`:'';$('safety-note').textContent=`${p.enabled?'Защита включена':'Защита выключена'} · версия настроек ${data.revision}. Минимальная выборка ${p.min_sample} писем на рассылку. Доли округлены для показа; сравнение выполняется точно. Это тестовые пороги, а не нормы SMTP-провайдера.`;const cell=(m,n)=>`${m.count}/${n} · ${m.percent}% / порог > ${m.threshold}%${m.exceeded?' — превышен':''}`;table($('safety-metrics'),['Рассылка','Выборка','Любые ошибки','Постоянные ошибки','Жалобы'],data.campaigns.map(c=>[`${c.name} (#${c.campaign_id})`,`${c.sample} · ${c.enough_data?'достаточно данных':'ожидание минимальной выборки'}`,cell(c.metrics.errors,c.sample),cell(c.metrics.permanent,c.sample),cell(c.metrics.complaints,c.sample)]));}
function text(tag,value){const el=document.createElement(tag);el.textContent=value??'';return el;}
function date(v){return new Date(v).toLocaleString('ru-RU',{timeZone:'Asia/Qyzylorda'});}
function button(label,fn){const b=text('button',label);b.className='outline';b.type='button';b.onclick=()=>mutate(fn);return b;}
function table(host,headers,rows){const t=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr');headers.forEach(h=>tr.append(text('th',h)));head.append(tr);t.append(head);const body=document.createElement('tbody');rows.forEach(values=>{const tr=document.createElement('tr');values.forEach((v,i)=>{const td=document.createElement('td');td.dataset.label=headers[i];if(v instanceof Node)td.append(v);else td.textContent=v??'';tr.append(td);});body.append(tr);});t.append(body);host.replaceChildren(t);if(!rows.length)host.append(text('p','Пока нет записей.'));}
async function post(url,data){return api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:'simulation',test_only:true,send:false,...data})});}
function controls(){for(const b of page.querySelectorAll('button'))b.disabled=busy;for(const el of page.querySelectorAll('input,select'))el.disabled=busy;$('safety').hidden=!id;for(const b of $('controls').querySelectorAll('button')){const a=b.dataset.action;b.disabled=busy||!id||(a==='pause'?current?.state!=='running':a==='resume'?current?.state!=='paused':a==='cancel'?current?.state==='cancelled':current?.state!=='running');}for(const el of $('safety-form').querySelectorAll('input,button'))el.disabled=busy||!id||['cancelled','safety_stopped'].includes(current?.state);if(current){$('prev').disabled=busy||number<=1;$('next').disabled=busy||number>=current.pagination.pages;}}
async function mutate(fn){if(busy)return;busy=true;controls();$('status').textContent='';try{await fn();}catch(e){$('status').textContent=e.message;}finally{busy=false;controls();}}
async function lists(scenarioId){const [s,r]=await Promise.all([api('/api/automations'),api('/api/rehearsals')]);scenarios=s.scenarios;const selected=scenarioId||$('scenario').value;$('scenario').replaceChildren(new Option('Выберите сценарий',''));for(const row of scenarios)$('scenario').add(new Option(`${row.name} · версия ${row.revision}`,row.id));$('scenario').value=String(selected||'');$('session').replaceChildren(new Option('Выберите репетицию',''));for(const row of r.sessions)$('session').add(new Option(`#${row.id} · ${row.snapshot__name} · ${states[row.state]}`,row.id));if(!id&&r.sessions.length)id=String(r.sessions[0].id);$('session').value=id;}
async function report(){if(!id){current=null;$('summary').textContent='Выберите репетицию.';$('clock').textContent='';for(const key of ['counts','members','letters','logs','pagination'])$(key).replaceChildren();$('preview').hidden=true;controls();return;}const seq=++generation,params=new URLSearchParams({query:$('query').value,kind:$('kind').value,state:$('state').value,delivery_state:$('delivery-state').value,direction:$('direction').value,page:String(number)});const d=await api('/api/rehearsals/'+id+'?'+params);if(seq!==generation)return;current=d;safetyReport(d.safety);sessionStorage.setItem('rehearsal-id',id);$('summary').textContent=`${d.name} · версия ${d.revision} · ${states[d.state]}. Подготовлено: ${d.letters_total}. Отправлено: 0. Доставка: неизвестна.`;$('clock').textContent='Последний цикл: '+date(d.clock_at)+'; общие часы: '+date(d.frequency_clock_at||d.clock_at)+' (Asia/Qyzylorda)';const kind=$('kind').value;$('kind').replaceChildren(new Option('Все события',''));Object.entries(d.kinds).forEach(([key,label])=>$('kind').add(new Option(label,key)));$('kind').value=kind;const deliveryState=$('delivery-state').value;$('delivery-state').replaceChildren(new Option('Все результаты',''));Object.entries(d.delivery_states).forEach(([key,label])=>$('delivery-state').add(new Option(label,key)));$('delivery-state').value=deliveryState;$('delivery-note').textContent=`Только тест: до ${d.delivery_policy.max_attempts} условных попыток, задержки ${d.delivery_policy.retry_minutes.join(' и ')} минут. Повтор использует то же письмо и ждёт заданного результата. Постоянная ошибка и жалоба запрещают следующие шаги только здесь. Рабочие адреса и исключения не меняются.`;
$('counts').replaceChildren();for(const key of ['waiting','completed','blocked','exited','excluded','cancelled','safety_stopped']){const card=document.createElement('article');card.append(text('span',states[key]),text('strong',d.counts[key]||0));$('counts').append(card);}for(const [key,title]of [['open','Писем с открытием'],['click','Писем с переходом'],['unsubscribe','Писем с отпиской']]){const card=document.createElement('article');card.append(text('span',title),text('strong',d.events[key]||0));$('counts').append(card);}
for(const [key,title]of [['retry','Ожидают повтора'],['awaiting_result','Ждут результата'],['exhausted','Попытки исчерпаны'],['test_delivered','Условно доставлено']]){const card=document.createElement('article');card.append(text('span',title),text('strong',d.delivery_counts[key]||0));$('counts').append(card);}
for(const [key,title]of [['temporary_error','Писем с временной ошибкой'],['permanent_error','Писем с постоянной ошибкой'],['complaint','Писем с жалобой']]){const card=document.createElement('article');card.append(text('span',title+' (тест)'),text('strong',d.delivery_event_counts[key]||0));$('counts').append(card);}
$('member-note').textContent=`Участников всего: ${d.total_members}; по фильтру: ${d.members_matched}. Показаны первые 100, по email.`;table($('members'),['Email','Активность','Состояние','Шагов','Следующий срок','Причина'],d.members.map(m=>[m.email,m.activity,states[m.state],m.step,m.next_note?(m.next_at?m.next_note+': '+date(m.next_at):m.next_note):m.state==='waiting'?date(m.next_at):'—',m.detail]));
table($('letters'),['Email','Рассылка / шаг','Тема','Тестовая доставка','События','Действия'],d.letters.map(l=>{const actions=document.createElement('div');actions.className='actions';actions.append(button('Письмо и проверки',()=>preview(l.id)));for(const [kind,label]of [['open','Открытие'],['click','Переход'],['unsubscribe','Отписка']])actions.append(button(label,async()=>{await post('/api/rehearsals/'+id,{action:'event',letter_id:l.id,kind});await report();$('status').textContent='Тестовое событие учтено; следующие шаги перепроверены.';}));
const outcome=document.createElement('label');outcome.textContent=`Тестовый результат письма №${l.id}`;const select=document.createElement('select');for(const [value,label]of [['temporary_error','Временная ошибка'],['permanent_error','Постоянная ошибка'],['complaint','Жалоба'],['test_delivered','Условно доставлено']]){if(['temporary_error','test_delivered'].includes(value)&&(!['untested','awaiting_result'].includes(l.delivery_state)||d.state==='cancelled'))continue;select.add(new Option(label,value));}outcome.append(select);actions.append(outcome,button('Записать тестовый результат',async()=>{await post('/api/rehearsals/'+id,{action:'delivery_event',letter_id:l.id,attempt:l.attempt,kind:select.value,event_id:crypto.randomUUID(),detail:$('delivery-detail').value});await report();$('status').textContent='Тестовый результат записан. SMTP и рабочая база не используются.';}));const deliveryCell=document.createElement('div');deliveryCell.append(text('strong',d.delivery_states[l.delivery_state]),text('p',`Условная попытка: ${l.attempt} / ${d.delivery_policy.max_attempts}`));if(l.retry_at)deliveryCell.append(text('p','Повтор не раньше: '+date(l.retry_at)));if(l.delivery_detail)deliveryCell.append(text('p',l.delivery_detail));return [l.recipient,`#${l.campaign_id} / ${l.step}`,l.subject,deliveryCell,l.events.map(k=>d.kinds[k]||k).join(', ')||'Нет',actions];}));
table($('logs'),['Тестовое время','Email','Решение / событие','Описание'],d.history.map(e=>[date(e.occurred_at),e.recipient||'—',d.kinds[e.kind]||e.kind,e.detail]));number=d.pagination.page;$('pagination').textContent=`${number} / ${d.pagination.pages} · записей: ${d.pagination.total}`;controls();}
async function preview(letterId){const session=id,d=await api(`/api/rehearsals/${id}/letters/${letterId}`);if(session!==id)return;$('preview').hidden=false;$('subject').textContent=d.subject;$('checks').replaceChildren();table($('delivery-history'),['Тестовое время','Попытка','Результат','Описание'],d.delivery_events.map(e=>[date(e.occurred_at),e.attempt,current.kinds[e.kind]||e.kind,e.detail]));for(const c of d.checks.checks){const p=text('p',`${{pass:'✓',warning:'Замечание',pending:'Не подтверждено',fail:'Ошибка'}[c.status]} · ${c.title}: ${c.detail}`);$('checks').append(p);}const old=$('frame'),frame=old.cloneNode(false);old.replaceWith(frame);requestAnimationFrame(()=>frame.srcdoc=`<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:; font-src 'none'; form-action 'none'; base-uri 'none'">`+d.html);$('preview').scrollIntoView({block:'start'});}
$('create').onsubmit=e=>{e.preventDefault();mutate(async()=>{const s=scenarios.find(s=>String(s.id)===$('scenario').value);if(!s)throw Error('Выберите сохранённый сценарий.');const d=await post('/api/rehearsals',{scenario_id:s.id,revision:s.revision,safety_policy:readPolicy('rh-new-safety'),values:{name:$('name').value,company:$('company').value,city:$('city').value}});id=String(d.id);number=1;for(const key of ['query','state','kind','delivery-state'])$(key).value='';$('preview').hidden=true;await lists(s.id);await report();$('status').textContent='Репетиция создана. Подготовка и события не являются отправкой.';});};
$('safety-form').onsubmit=e=>{e.preventDefault();mutate(async()=>{await post('/api/rehearsals/'+id,{action:'safety_configure',policy_revision:current.safety.revision,policy:readPolicy('rh-safety')});await lists();await report();$('status').textContent='Пороги сохранены, тестовые показатели перепроверены.';});};
$('controls').onclick=e=>{const b=e.target.closest('button');if(!b)return;mutate(async()=>{await post('/api/rehearsals/'+id,b.dataset.minutes?{action:'advance',minutes:Number(b.dataset.minutes)}:{action:b.dataset.action});await lists();await report();});};
$('session').onchange=()=>mutate(async()=>{id=$('session').value;number=1;$('preview').hidden=true;await report();});$('filters').onsubmit=e=>{e.preventDefault();mutate(async()=>{number=1;await report();});};$('prev').onclick=()=>mutate(async()=>{number--;await report();});$('next').onclick=()=>mutate(async()=>{number++;await report();});$('refresh').onclick=()=>mutate(async()=>{await lists();await report();});
async function open(scenarioId){document.querySelectorAll('body>main').forEach(p=>p.hidden=true);side.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===nav));page.hidden=false;document.title='Сквозная репетиция';sessionStorage.setItem('open-rehearsals','1');await mutate(async()=>{await lists(scenarioId);await report();});}
nav.onclick=()=>open();side.addEventListener('click',e=>{const b=e.target.closest('button');if(b&&b!==nav){page.hidden=true;generation++;sessionStorage.removeItem('open-rehearsals');}});window.CampaignRehearsal={open,async openRun(runId){id=String(runId);number=1;for(const key of ['query','state','kind','delivery-state'])$(key).value='';$('preview').hidden=true;await open();}};
try{id=sessionStorage.getItem('rehearsal-id')||'';if(sessionStorage.getItem('open-rehearsals'))open();}catch{}
})();
